    private static var images: [String: NSImage] = [:]

    /// The mark alone, nil when there is none or AppKit cannot read it.
    static func mark(for pluginID: String) -> NSImage? {
        if let image = images[pluginID] { return image }
        guard let svg = marks[pluginID], let image = NSImage(data: Data(svg.utf8)), image.isValid else { return nil }
        images[pluginID] = image
        return image
    }

    /// The mark on its white tile, `size` points square. The tile stays white in dark mode, so
    /// a black or dark brand color still reads; it is drawn at display time, sharp at any scale.
    static func tile(for pluginID: String, size: CGFloat) -> NSImage? {
        guard let mark = mark(for: pluginID) else { return nil }
        let image = NSImage(size: NSSize(width: size, height: size), flipped: false) { rect in
            let line = max(0.5, size / 48)
            let tile = NSBezierPath(
                roundedRect: rect.insetBy(dx: line / 2, dy: line / 2), xRadius: size * 0.25, yRadius: size * 0.25)
            NSColor.white.setFill()
            tile.fill()
            NSColor(white: 0, alpha: 0.12).setStroke()
            tile.lineWidth = line
            tile.stroke()
            mark.draw(in: rect.insetBy(dx: size * 0.2, dy: size * 0.2))
            return true
        }
        return image
    }
}
